from datetime import datetime, timezone

root = os.path.expanduser("~/.claude/projects")

def parse(ts):
    return datetime.fromisoformat(ts.replace("Z","+00:00"))

gaps = []
for main in glob.glob(os.path.join(root, "*", "*.jsonl")):
    session_id = os.path.basename(main)[:-6]
    session_dir = os.path.join(os.path.dirname(main), session_id)
    if not os.path.isdir(os.path.join(session_dir, "subagents")):
        continue  # only care about sessions that spawned workers
    prev = None
    maxgap = 0
    first_ts = None
    with open(main, encoding="utf-8", errors="replace") as f:
        for line in f:
            line = line.strip()
            if not line.startswith("{"):
                continue
            try:
                rec = json.loads(line)
            except ValueError:
                continue
            ts = rec.get("timestamp")
            if not (isinstance(ts, str) and ts):
                continue
            if first_ts is None:
                first_ts = ts
            try:
                dt = parse(ts)
            except Exception:
                continue
            if prev is not None:
                gap = (dt - prev).total_seconds()
                if gap > maxgap:
                    maxgap = gap
            prev = dt
    if maxgap > 3600:  # gap over an hour = plausible resume/restart
        gaps.append((maxgap, main, first_ts))

gaps.sort(key=lambda x: -x[0])
for g in gaps[:15]:
    print(g[0]/3600, "hours gap;", g[1], "first:", g[2])
